"use client";

import { useEffect, useState } from "react";

type VerificationDocument = { id: string; document_type: string; status: "pending" | "approved" | "rejected"; rejection_reason: string | null; submitted_at: string; reviewed_at: string | null };
export function VendorVerificationDocuments() {
  const [documents, setDocuments] = useState<VerificationDocument[]>([]);
  const [documentType, setDocumentType] = useState("Business registration");
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const load = async () => { const response = await fetch("/api/vendors/verification-documents", { cache: "no-store" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Documents could not be loaded."); setDocuments(data.documents ?? []); };
  useEffect(() => { void load().catch((cause) => setError(cause instanceof Error ? cause.message : "Documents could not be loaded.")); }, []);
  const upload = async (event: React.FormEvent) => { event.preventDefault(); if (!file) return; setBusy(true); setError(null); setNotice(null); try { const body = new FormData(); body.set("documentType", documentType); body.set("file", file); const response = await fetch("/api/vendors/verification-documents", { method: "POST", body }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Document upload failed."); setFile(null); setNotice("Document uploaded for review."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Document upload failed."); } finally { setBusy(false); } };
  return <section className="space-y-4 rounded-3xl border border-[#EAD2B0] bg-[#FFFCF6] p-5 dark:border-[#4D3331] dark:bg-[#241918]"><form onSubmit={(event) => void upload(event)} className="space-y-3"><h3 className="font-serif text-xl font-bold text-[#681B1D] dark:text-[#EAD2B0]">Submit a verification document</h3><p className="text-sm text-[#7D6B63]">Files are stored in a private bucket and visible only to your business and authorized administrators.</p><div className="grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><label className="text-xs font-semibold">Document type<select value={documentType} onChange={(event) => setDocumentType(event.target.value)} className="mt-1 w-full rounded-xl border border-[#EAD2B0] bg-[#FFF3E3] p-2.5 text-sm dark:border-[#4D3331] dark:bg-[#1A1211]"><option>Business registration</option><option>Tax registration</option><option>Identity document</option><option>Address proof</option><option>Other</option></select></label><label className="text-xs font-semibold">PDF or image, up to 10 MB<input required type="file" accept="application/pdf,image/jpeg,image/png,image/webp" onChange={(event) => setFile(event.target.files?.[0] || null)} className="mt-1 block w-full text-xs"/></label><button disabled={busy || !file} className="self-end rounded-xl bg-[#681B1D] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{busy ? "Uploading…" : "Upload document"}</button></div></form>{error && <p role="alert" className="text-sm text-rose-700">{error}</p>}{notice && <p role="status" className="text-sm text-emerald-700">{notice}</p>}<div className="space-y-2">{documents.map((document) => <div key={document.id} className="flex flex-wrap items-start justify-between gap-2 rounded-xl border border-[#EAD2B0] p-3 text-sm dark:border-[#4D3331]"><span><b>{document.document_type}</b><span className="ml-2 text-xs text-[#7D6B63]">Submitted {new Date(document.submitted_at).toLocaleDateString("en-IN")}</span>{document.rejection_reason && <span className="mt-1 block text-xs text-rose-700">{document.rejection_reason}</span>}</span><span className={`rounded-full px-2.5 py-1 text-xs font-semibold capitalize ${document.status === "approved" ? "bg-emerald-100 text-emerald-800" : document.status === "rejected" ? "bg-rose-100 text-rose-800" : "bg-amber-100 text-amber-800"}`}>{document.status}</span></div>)}{!documents.length && <p className="rounded-xl bg-[#FFF3E3] p-4 text-sm text-[#7D6B63] dark:bg-[#1A1211]">No submitted documents yet.</p>}</div></section>;
}
